traces.inference_trace:
Reverse union-find: apply all hits first, then add bricks back in reverse order and measure how much the roof-connected component grows.

1. **Mark hits.** Copy the grid. For each hit, decrement the cell. A hit on a brick goes from 1 to 0, and a hit on an empty cell goes from 0 to -1. Since hits are unique, a cell that ends at 0 was originally a brick.

2. **Build the final state.** Create a DSU with `m*n + 1` nodes, where the extra node `m*n` is the roof, and track component sizes.
   - Union every remaining brick in row 0 with the roof.
   - Union every remaining brick with its brick neighbors to the right and below.

3. **Process hits in reverse.** For each hit:
   - If the cell is now 0, it was a brick, so restore it to 1. Otherwise the answer is 0.
   - Record `prev`, the size of the roof component.
   - If the cell is in row 0, union it with the roof.
   - Union it with each adjacent brick.
   - Record `cur`, the new size of the roof component.
   - The answer is `max(0, cur - prev - 1)`. The `-1` excludes the restored brick itself, which was erased rather than fallen.

4. **Implement `find` iteratively** with path halving to avoid deep recursion on large grids.

```typescript
function hitBricks(grid: number[][], hits: number[][]): number[] {
    const m = grid.length, n = grid[0].length;
    const g = grid.map(r => r.slice());
    for (const [r, c] of hits) g[r][c]--;
    const N = m * n;
    const parent = new Int32Array(N + 1);
    const size = new Int32Array(N + 1);
    for (let i = 0; i <= N; i++) { parent[i] = i; size[i] = 1; }
    const find = (x: number): number => {
        while (parent[x] !== x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    };
    const union = (a: number, b: number) => {
        let ra = find(a), rb = find(b);
        if (ra === rb) return;
        if (size[ra] < size[rb]) { const t = ra; ra = rb; rb = t; }
        parent[rb] = ra;
        size[ra] += size[rb];
    };
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            if (g[i][j] !== 1) continue;
            const id = i * n + j;
            if (i === 0) union(id, N);
            if (i + 1 < m && g[i + 1][j] === 1) union(id, id + n);
            if (j + 1 < n && g[i][j + 1] === 1) union(id, id + 1);
        }
    }
    const dr = [1, -1, 0, 0], dc = [0, 0, 1, -1];
    const res = new Array(hits.length).fill(0);
    for (let k = hits.length - 1; k >= 0; k--) {
        const [r, c] = hits[k];
        if (g[r][c] !== 0) continue;
        g[r][c] = 1;
        const prev = size[find(N)];
        const id = r * n + c;
        if (r === 0) union(id, N);
        for (let d = 0; d < 4; d++) {
            const nr = r + dr[d], nc = c + dc[d];
            if (nr < 0 || nr >= m || nc < 0 || nc >= n) continue;
            if (g[nr][nc] === 1) union(id, nr * n + nc);
        }
        const cur = size[find(N)];
        res[k] = Math.max(0, cur - prev - 1);
    }
    return res;
};
```

