```typescript
function areOccurrencesEqual(s: string): boolean {
    const cnt: number[] = new Array(26).fill(0);
    for (let i = 0; i < s.length; i++) {
        const c = s.charCodeAt(i) - 97;
        if (c >= 0 && c < 26) cnt[c]++;
    }
    let f = 0;
    for (const c of cnt) {
        if (c === 0) continue;
        if (f === 0) f = c;
        else if (c !== f) return false;
    }
    return true;
};
```

