function numFactoredBinaryTrees(arr: number[]): number {
    const MOD = 1000000007n;
    const a = [...arr].sort((x, y) => x - y);
    const n = a.length;
    const idx = new Map<number, number>();
    a.forEach((v, i) => idx.set(v, i));
    const dp: bigint[] = new Array(n).fill(1n);
    let total = 0n;
    for (let i = 0; i < n; i++) {
        let s = 1n;
        for (let j = 0; j < i; j++) {
            if (a[i] % a[j] === 0) {
                const q = a[i] / a[j];
                const k = idx.get(q);
                if (k !== undefined) {
                    s = (s + dp[j] * dp[k]) % MOD;
                }
            }
        }
        dp[i] = s;
        total = (total + s) % MOD;
    }
    return Number(total);
};
```

