    let dx = -1, dy = -2, px = -1, py = -1;
    const stack: [TreeNode, number, number][] = [];
    if (root) stack.push([root, -1, 0]);
    while (stack.length) {
        const [node, parent, depth] = stack.pop()!;
        if (node.val === x) { dx = depth; px = parent; }
        if (node.val === y) { dy = depth; py = parent; }
        if (node.left) stack.push([node.left, node.val, depth + 1]);
        if (node.right) stack.push([node.right, node.val, depth + 1]);
    }
    return dx === dy && px !== py;
};
```

