Two strings are close exactly when three conditions hold:

1. **Same length.** Neither operation changes the length.
2. **Same set of characters.** Operation 2 only swaps between characters that already exist, so no new character can appear and none can disappear.
3. **Same multiset of frequencies.** Operation 1 reorders characters freely without changing any count. Operation 2 swaps the counts of two existing characters, which permutes the frequency values but never changes them.

To check these, count each letter in both strings, compare which letters are present, then sort both frequency arrays and compare them.

```typescript
function closeStrings(word1: string, word2: string): boolean {
    if (word1.length !== word2.length) return false;
    const c1 = new Array(26).fill(0);
    const c2 = new Array(26).fill(0);
    for (let i = 0; i < word1.length; i++) c1[word1.charCodeAt(i) - 97]++;
    for (let i = 0; i < word2.length; i++) c2[word2.charCodeAt(i) - 97]++;
    for (let i = 0; i < 26; i++) {
        if ((c1[i] === 0) !== (c2[i] === 0)) return false;
    }
    c1.sort((a, b) => a - b);
    c2.sort((a, b) => a - b);
    for (let i = 0; i < 26; i++) {
        if (c1[i] !== c2[i]) return false;
    }
    return true;
};
```

