Approach: breadth-first search, level by level. The first leaf reached is on the shallowest level, so its level number is the minimum depth. An iterative BFS also avoids deep recursion on skewed trees with up to 10^5 nodes.

Steps:
1. If the tree is empty, return 0.
2. Start the queue with the root at depth 1.
3. For each level, check every node. If a node has no children, return the current depth.
4. Otherwise, add its non-null children to the next level and increase the depth by 1.

```typescript
/**
 * Definition for a binary tree node.
 * class TreeNode {
 *     val: number
 *     left: TreeNode | null
 *     right: TreeNode | null
 *     constructor(val?: number, left?: TreeNode | null, right?: TreeNode | null) {
 *         this.val = (val===undefined ? 0 : val)
 *         this.left = (left===undefined ? null : left)
 *         this.right = (right===undefined ? null : right)
 *     }
 * }
 */

function minDepth(root: TreeNode | null): number {
    if (root === null) return 0;
    let level: TreeNode[] = [root];
    let depth = 1;
    while (level.length > 0) {
        const next: TreeNode[] = [];
        for (const node of level) {
            if (node.left === null && node.right === null) return depth;
            if (node.left !== null) next.push(node.left);
            if (node.right !== null) next.push(node.right);
        }
        level = next;
        depth++;
    }
    return depth;
};
```

