        if (d < lo) lo = d;
        if (d > hi) hi = d;
    }
    const can = (day: number): boolean => {
        let run = 0, cnt = 0;
        for (let i = 0; i < n; i++) {
            if (bloomDay[i] <= day) {
                run++;
                if (run === k) {
                    cnt++;
                    run = 0;
                    if (cnt >= m) return true;
