            cnt[y % 10]++;
            y = Math.floor(y / 10);
        }
        let ok = true;
        for (let d = 0; d < 10; d++) {
            if (cnt[d] !== 0 && cnt[d] !== d) { ok = false; break; }
        }
        if (ok) return x;
    }
};
```

