traces.inference_trace:
Split each cell into 4 triangles: top (0), right (1), bottom (2), left (3). Union-find then works as follows.

**Inside a cell:**
- For `' '`, union all four triangles.
- For `'/'`, union top with left (0–3) and right with bottom (1–2).
- For `'\'`, union top with right (0–1) and bottom with left (2–3).

**Between neighbouring cells:**
- A cell's bottom triangle joins the top triangle of the cell below.
- A cell's right triangle joins the left triangle of the cell to its right.

The answer is the number of disjoint components.

```typescript
function regionsBySlashes(grid: string[]): number {
    const n = grid.length;
    const size = 4 * n * n;
    const parent = new Array(size);
    for (let i = 0; i < size; i++) parent[i] = i;
    let count = size;
    const find = (x: number): number => {
        while (parent[x] !== x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    };
    const union = (a: number, b: number) => {
        const ra = find(a), rb = find(b);
        if (ra !== rb) {
            parent[ra] = rb;
            count--;
        }
    };
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            const base = 4 * (i * n + j);
            const c = grid[i][j];
            if (c === '/') {
                union(base + 0, base + 3);
                union(base + 1, base + 2);
            } else if (c === '\\') {
                union(base + 0, base + 1);
                union(base + 2, base + 3);
            } else {
                union(base + 0, base + 1);
                union(base + 1, base + 2);
                union(base + 2, base + 3);
            }
            if (i + 1 < n) {
                const below = 4 * ((i + 1) * n + j);
                union(base + 2, below + 0);
            }
            if (j + 1 < n) {
                const right = 4 * (i * n + j + 1);
                union(base + 1, right + 3);
            }
        }
    }
    return count;
};
```

