Build a trie of the reversed words. Keep the stream in a buffer, but only the most recent `maxLen` characters, where `maxLen` is the length of the longest word. On each query, walk the trie from the newest character backward. Return true as soon as we reach a node that ends a word.

Implementation details:
- The trie uses flat typed arrays: 26 children per node and an end flag.
- Total trie size is at most 2000 × 200 = 400k nodes, so 400k × 26 ≈ 10.4M ints. As an Int32Array that is about 41MB, which is acceptable.
- To avoid over-allocating, count the total characters first and allocate `total + 1` nodes.
- The stream buffer is a circular buffer of size `maxLen`, holding character codes.

```typescript
class StreamChecker {
    private children: Int32Array;
    private isEnd: Uint8Array;
    private buf: Uint8Array;
    private maxLen: number;
    private pos: number = 0;
    private count: number = 0;

    constructor(words: string[]) {
        let total = 1;
        let maxLen = 0;
        for (const w of words) {
            total += w.length;
            if (w.length > maxLen) maxLen = w.length;
        }
        this.children = new Int32Array(total * 26);
        this.isEnd = new Uint8Array(total);
        let nodes = 1;
        for (const w of words) {
            let node = 0;
            for (let i = w.length - 1; i >= 0; i--) {
                const c = w.charCodeAt(i) - 97;
                const idx = node * 26 + c;
                if (this.children[idx] === 0) {
                    this.children[idx] = nodes++;
                }
                node = this.children[idx];
            }
            this.isEnd[node] = 1;
        }
        this.maxLen = maxLen;
        this.buf = new Uint8Array(maxLen);
    }

    query(letter: string): boolean {
        const m = this.maxLen;
        this.buf[this.pos] = letter.charCodeAt(0) - 97;
        this.pos = (this.pos + 1) % m;
        if (this.count < m) this.count++;
        let node = 0;
        let p = this.pos;
        for (let k = 0; k < this.count; k++) {
            p = p - 1;
            if (p < 0) p += m;
            const next = this.children[node * 26 + this.buf[p]];
            if (next === 0) return false;
            node = next;
            if (this.isEnd[node]) return true;
        }
        return false;
    }
}

