Count the soldiers in each row with a binary search, since every row is all 1's followed by all 0's. Then sort the row indices by soldier count, breaking ties by the smaller index, and return the first `k`.

```typescript
function kWeakestRows(mat: number[][], k: number): number[] {
    const counts: number[] = mat.map(row => {
        let lo = 0, hi = row.length;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (row[mid] === 1) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    });
    const idx = counts.map((_, i) => i);
    idx.sort((a, b) => counts[a] - counts[b] || a - b);
    return idx.slice(0, k);
};
```

