traces.inference_trace:
Combine both sentences and count how often each word appears overall. A word is uncommon exactly when its total count is 1: it then appears once in one sentence and not at all in the other.

```typescript
function uncommonFromSentences(s1: string, s2: string): string[] {
    const count = new Map<string, number>();
    for (const w of (s1 + " " + s2).split(" ")) {
        if (w.length === 0) continue;
        count.set(w, (count.get(w) ?? 0) + 1);
    }
    const res: string[] = [];
    for (const [w, c] of count) {
        if (c === 1) res.push(w);
    }
    return res;
};
```

